/* ============================================================
   SONGWRITING STUDIO — THE CURRICULUM AND ITS SMALL LISTS

   Eleven stages and 131 exercises, paraphrased from the books named on each
   (Pattison, Writing Better Lyrics and Songwriting Without Boundaries;
   Stolpe, Writing Better Songs; Kachulis, The Songwriter's Workshop:
   Harmony and Melody; Hooktheory I), with the source on every exercise.
   No passage of any book and no song lyric is quoted. Data only: the
   room reads it, nothing writes to it.

   An exercise: {id, title, source, purpose, instructions[], outputFields[],
   selfCheck?, toolLink?, constraints?, reflection?, levels?}.
   ============================================================ */
const SNG_STAGES = [{"id":0,"name":"Opening the Studio","subtitle":"Orientation","promise":"Prove the loop exists — write a song in an hour, badly.","books":["Hooktheory I","WBL ch1"],"exercises":[{"id":"0.1","title":"Set Your Instrument","source":"Setup","purpose":"Establish your vocal range so tools can warn you when melodies go too high or low.","instructions":["Sit at your piano.","Starting from middle C, sing downward until you can't produce a clear tone. Record that note.","Sing upward from middle C until you strain. Record that note.","Enter both in the fields below."],"outputFields":["Lowest comfortable note","Highest comfortable note"],"selfCheck":"Can you sing both boundary notes clearly three times?"},{"id":"0.2","title":"Numbers Not Letters","source":"Hooktheory I ch1","purpose":"Start hearing music in relative terms — scale degrees and Roman numerals — so you can think in any key.","instructions":["Pick a song you love and can hum from memory.","At the piano, find the key (the note that feels like 'home').","Figure out the first melody phrase as scale degrees (1 through 7).","Figure out the chords as Roman numerals (I, ii, iii, IV, V, vi).","Write them down below."],"outputFields":["Song title","Key","Melody as scale degrees","Chords as Roman numerals"],"toolLink":"chord-lab","selfCheck":"Does singing your scale degrees over the chords sound right?"},{"id":"0.3","title":"First Dive: Object Writing","source":"Pattison, Writing Better Lyrics ch1","purpose":"Experience sense-bound free writing for the first time. The seven senses (sight, sound, taste, touch, smell, body/organic, motion/kinesthetic) will become your primary creative engine.","instructions":["Set the timer for 10 minutes.","The prompt word is: puddle.","Write freely using all seven senses — what you see, hear, taste, touch, smell, feel inside your body, and how your body moves.","Let associations flow. No rhyme, no rhythm, no full sentences needed.","When the timer stops, STOP — even mid-word. This discipline matters."],"constraints":"10 minutes, hard stop","outputFields":["Object writing output"],"toolLink":"object-writing","selfCheck":"Did you touch at least 4 of the 7 senses?","reflection":"What surprised you? Which senses were hardest to reach?"},{"id":"0.4","title":"A Song in an Hour, Badly","source":"General practice","purpose":"Prove the entire songwriting loop exists: chords → melody → words → done. Remove pressure by celebrating finishing, not quality.","instructions":["Open the Chord Lab and loop I–V–vi–IV in C major.","Talk-sing a verse and chorus about your day today. Don't aim for good — aim for done.","Record a voice memo of your performance.","Celebrate: you wrote a complete song. Most people never finish one."],"constraints":"1 hour maximum","outputFields":["Voice memo or description","Any lyrics you remember"],"toolLink":"chord-lab","selfCheck":"Did you finish? That's the only criterion.","reflection":"How did it feel to finish something imperfect?"}],"stageSong":"A 4-line verse using images from your object writing, talk-sung over a simple chord loop."},{"id":1,"name":"The Senses","subtitle":"Lyric Foundations","promise":"Train your senses to generate raw material on demand — 14 days of diving deep.","books":["Pattison, Songwriting Without Boundaries","Pattison, WBL ch1–2","Stolpe ch1–3"],"exercises":[{"id":"1.1","title":"Day 1: Object Writing — What","source":"Pattison, SWB Challenge 1 Day 1","purpose":"Build speed and sensory depth through daily timed writing. \"What\" prompts focus on concrete objects.","instructions":["Today's focus: What. Suggested prompt: \"sky\" (or pick your own).","Round 1: Set timer for 5 minutes. Write using all 7 senses. Stop at the buzzer.","Round 2: Fresh start, same prompt. 10 minutes. Go deeper.","Round 3: Fresh start. 90 seconds. Pure intensity — the 'kamikaze' round.","After each round, note which senses you used."],"constraints":"5 min / 10 min / 90 sec — hard stops","outputFields":["5-minute piece","10-minute piece","90-second piece","Senses used"],"toolLink":"object-writing","selfCheck":"Did you stop exactly at the buzzer? Did you reach at least 5 senses in the 10-minute round?"},{"id":"1.2","title":"Day 2: Object Writing — What","source":"Pattison, SWB Challenge 1 Day 2","purpose":"Build speed and sensory depth through daily timed writing. \"What\" prompts focus on concrete objects.","instructions":["Today's focus: What. Suggested prompt: \"bathroom mirror\" (or pick your own).","Round 1: Set timer for 5 minutes. Write using all 7 senses. Stop at the buzzer.","Round 2: Fresh start, same prompt. 10 minutes. Go deeper.","Round 3: Fresh start. 90 seconds. Pure intensity — the 'kamikaze' round.","After each round, note which senses you used."],"constraints":"5 min / 10 min / 90 sec — hard stops","outputFields":["5-minute piece","10-minute piece","90-second piece","Senses used"],"toolLink":"object-writing","selfCheck":"Did you stop exactly at the buzzer? Did you reach at least 5 senses in the 10-minute round?"},{"id":"1.3","title":"Day 3: Object Writing — What","source":"Pattison, SWB Challenge 1 Day 3","purpose":"Build speed and sensory depth through daily timed writing. \"What\" prompts focus on concrete objects.","instructions":["Today's focus: What. Suggested prompt: \"umbrella\" (or pick your own).","Round 1: Set timer for 5 minutes. Write using all 7 senses. Stop at the buzzer.","Round 2: Fresh start, same prompt. 10 minutes. Go deeper.","Round 3: Fresh start. 90 seconds. Pure intensity — the 'kamikaze' round.","After each round, note which senses you used."],"constraints":"5 min / 10 min / 90 sec — hard stops","outputFields":["5-minute piece","10-minute piece","90-second piece","Senses used"],"toolLink":"object-writing","selfCheck":"Did you stop exactly at the buzzer? Did you reach at least 5 senses in the 10-minute round?"},{"id":"1.4","title":"Day 4: Object Writing — What","source":"Pattison, SWB Challenge 1 Day 4","purpose":"Build speed and sensory depth through daily timed writing. \"What\" prompts focus on concrete objects.","instructions":["Today's focus: What. Suggested prompt: \"curb\" (or pick your own).","Round 1: Set timer for 5 minutes. Write using all 7 senses. Stop at the buzzer.","Round 2: Fresh start, same prompt. 10 minutes. Go deeper.","Round 3: Fresh start. 90 seconds. Pure intensity — the 'kamikaze' round.","After each round, note which senses you used."],"constraints":"5 min / 10 min / 90 sec — hard stops","outputFields":["5-minute piece","10-minute piece","90-second piece","Senses used"],"toolLink":"object-writing","selfCheck":"Did you stop exactly at the buzzer? Did you reach at least 5 senses in the 10-minute round?"},{"id":"1.5","title":"Day 5: Object Writing — What","source":"Pattison, SWB Challenge 1 Day 5","purpose":"Build speed and sensory depth through daily timed writing. \"What\" prompts focus on concrete objects.","instructions":["Today's focus: What. Suggested prompt: \"movie theater\" (or pick your own).","Round 1: Set timer for 5 minutes. Write using all 7 senses. Stop at the buzzer.","Round 2: Fresh start, same prompt. 10 minutes. Go deeper.","Round 3: Fresh start. 90 seconds. Pure intensity — the 'kamikaze' round.","After each round, note which senses you used."],"constraints":"5 min / 10 min / 90 sec — hard stops","outputFields":["5-minute piece","10-minute piece","90-second piece","Senses used"],"toolLink":"object-writing","selfCheck":"Did you stop exactly at the buzzer? Did you reach at least 5 senses in the 10-minute round?"},{"id":"1.6","title":"Day 6: Object Writing — Who","source":"Pattison, SWB Challenge 1 Day 6","purpose":"Build speed and sensory depth through daily timed writing. \"Who\" prompts build empathy by writing as someone else.","instructions":["Today's focus: Who. Suggested prompt: \"sailor\" (or pick your own).","Round 1: Set timer for 5 minutes. Write using all 7 senses. Stop at the buzzer.","Round 2: Fresh start, same prompt. 10 minutes. Go deeper.","Round 3: Fresh start. 90 seconds. Pure intensity — the 'kamikaze' round.","After each round, note which senses you used."],"constraints":"5 min / 10 min / 90 sec — hard stops","outputFields":["5-minute piece","10-minute piece","90-second piece","Senses used"],"toolLink":"object-writing","selfCheck":"Did you stop exactly at the buzzer? Did you reach at least 5 senses in the 10-minute round?"},{"id":"1.7","title":"Day 7: Object Writing — Who","source":"Pattison, SWB Challenge 1 Day 7","purpose":"Build speed and sensory depth through daily timed writing. \"Who\" prompts build empathy by writing as someone else.","instructions":["Today's focus: Who. Suggested prompt: \"waitress\" (or pick your own).","Round 1: Set timer for 5 minutes. Write using all 7 senses. Stop at the buzzer.","Round 2: Fresh start, same prompt. 10 minutes. Go deeper.","Round 3: Fresh start. 90 seconds. Pure intensity — the 'kamikaze' round.","After each round, note which senses you used."],"constraints":"5 min / 10 min / 90 sec — hard stops","outputFields":["5-minute piece","10-minute piece","90-second piece","Senses used"],"toolLink":"object-writing","selfCheck":"Did you stop exactly at the buzzer? Did you reach at least 5 senses in the 10-minute round?"},{"id":"1.8","title":"Day 8: Object Writing — Who","source":"Pattison, SWB Challenge 1 Day 8","purpose":"Build speed and sensory depth through daily timed writing. \"Who\" prompts build empathy by writing as someone else.","instructions":["Today's focus: Who. Suggested prompt: \"trucker\" (or pick your own).","Round 1: Set timer for 5 minutes. Write using all 7 senses. Stop at the buzzer.","Round 2: Fresh start, same prompt. 10 minutes. Go deeper.","Round 3: Fresh start. 90 seconds. Pure intensity — the 'kamikaze' round.","After each round, note which senses you used."],"constraints":"5 min / 10 min / 90 sec — hard stops","outputFields":["5-minute piece","10-minute piece","90-second piece","Senses used"],"toolLink":"object-writing","selfCheck":"Did you stop exactly at the buzzer? Did you reach at least 5 senses in the 10-minute round?"},{"id":"1.9","title":"Day 9: Object Writing — When","source":"Pattison, SWB Challenge 1 Day 9","purpose":"Build speed and sensory depth through daily timed writing. \"When\" prompts anchor writing in a specific moment.","instructions":["Today's focus: When. Suggested prompt: \"six in the morning\" (or pick your own).","Round 1: Set timer for 5 minutes. Write using all 7 senses. Stop at the buzzer.","Round 2: Fresh start, same prompt. 10 minutes. Go deeper.","Round 3: Fresh start. 90 seconds. Pure intensity — the 'kamikaze' round.","After each round, note which senses you used."],"constraints":"5 min / 10 min / 90 sec — hard stops","outputFields":["5-minute piece","10-minute piece","90-second piece","Senses used"],"toolLink":"object-writing","selfCheck":"Did you stop exactly at the buzzer? Did you reach at least 5 senses in the 10-minute round?"},{"id":"1.10","title":"Day 10: Object Writing — When","source":"Pattison, SWB Challenge 1 Day 10","purpose":"Build speed and sensory depth through daily timed writing. \"When\" prompts anchor writing in a specific moment.","instructions":["Today's focus: When. Suggested prompt: \"late evening\" (or pick your own).","Round 1: Set timer for 5 minutes. Write using all 7 senses. Stop at the buzzer.","Round 2: Fresh start, same prompt. 10 minutes. Go deeper.","Round 3: Fresh start. 90 seconds. Pure intensity — the 'kamikaze' round.","After each round, note which senses you used."],"constraints":"5 min / 10 min / 90 sec — hard stops","outputFields":["5-minute piece","10-minute piece","90-second piece","Senses used"],"toolLink":"object-writing","selfCheck":"Did you stop exactly at the buzzer? Did you reach at least 5 senses in the 10-minute round?"},{"id":"1.11","title":"Day 11: Object Writing — When","source":"Pattison, SWB Challenge 1 Day 11","purpose":"Build speed and sensory depth through daily timed writing. \"When\" prompts anchor writing in a specific moment.","instructions":["Today's focus: When. Suggested prompt: \"wedding rehearsal dinner\" (or pick your own).","Round 1: Set timer for 5 minutes. Write using all 7 senses. Stop at the buzzer.","Round 2: Fresh start, same prompt. 10 minutes. Go deeper.","Round 3: Fresh start. 90 seconds. Pure intensity — the 'kamikaze' round.","After each round, note which senses you used."],"constraints":"5 min / 10 min / 90 sec — hard stops","outputFields":["5-minute piece","10-minute piece","90-second piece","Senses used"],"toolLink":"object-writing","selfCheck":"Did you stop exactly at the buzzer? Did you reach at least 5 senses in the 10-minute round?"},{"id":"1.12","title":"Day 12: Object Writing — Where","source":"Pattison, SWB Challenge 1 Day 12","purpose":"Build speed and sensory depth through daily timed writing. \"Where\" prompts ground writing in a physical place.","instructions":["Today's focus: Where. Suggested prompt: \"cliff by the ocean\" (or pick your own).","Round 1: Set timer for 5 minutes. Write using all 7 senses. Stop at the buzzer.","Round 2: Fresh start, same prompt. 10 minutes. Go deeper.","Round 3: Fresh start. 90 seconds. Pure intensity — the 'kamikaze' round.","After each round, note which senses you used."],"constraints":"5 min / 10 min / 90 sec — hard stops","outputFields":["5-minute piece","10-minute piece","90-second piece","Senses used"],"toolLink":"object-writing","selfCheck":"Did you stop exactly at the buzzer? Did you reach at least 5 senses in the 10-minute round?"},{"id":"1.13","title":"Day 13: Object Writing — Where","source":"Pattison, SWB Challenge 1 Day 13","purpose":"Build speed and sensory depth through daily timed writing. \"Where\" prompts ground writing in a physical place.","instructions":["Today's focus: Where. Suggested prompt: \"canoe on a river\" (or pick your own).","Round 1: Set timer for 5 minutes. Write using all 7 senses. Stop at the buzzer.","Round 2: Fresh start, same prompt. 10 minutes. Go deeper.","Round 3: Fresh start. 90 seconds. Pure intensity — the 'kamikaze' round.","After each round, note which senses you used."],"constraints":"5 min / 10 min / 90 sec — hard stops","outputFields":["5-minute piece","10-minute piece","90-second piece","Senses used"],"toolLink":"object-writing","selfCheck":"Did you stop exactly at the buzzer? Did you reach at least 5 senses in the 10-minute round?"},{"id":"1.14","title":"Day 14: Object Writing — Where","source":"Pattison, SWB Challenge 1 Day 14","purpose":"Build speed and sensory depth through daily timed writing. \"Where\" prompts ground writing in a physical place.","instructions":["Today's focus: Where. Suggested prompt: \"hospital waiting room\" (or pick your own).","Round 1: Set timer for 5 minutes. Write using all 7 senses. Stop at the buzzer.","Round 2: Fresh start, same prompt. 10 minutes. Go deeper.","Round 3: Fresh start. 90 seconds. Pure intensity — the 'kamikaze' round.","After each round, note which senses you used."],"constraints":"5 min / 10 min / 90 sec — hard stops","outputFields":["5-minute piece","10-minute piece","90-second piece","Senses used"],"toolLink":"object-writing","selfCheck":"Did you stop exactly at the buzzer? Did you reach at least 5 senses in the 10-minute round?","reflection":"Look back at Day 1. How has your sensory range expanded?"},{"id":"1.15","title":"Show Before You Tell","source":"Pattison, WBL ch2","purpose":"Learn the 'Sister Mary Elizabeth Rule': concrete sense images placed first create experience; abstractions placed first merely inform. Colors drip down, not up.","instructions":["Write a 4-line verse that TELLS an emotion (e.g., 'I was so sad that day').","Now rewrite it: move a concrete sense image to the very first line.","Compare how each version feels when read aloud.","The image-first version should create the feeling without naming it."],"outputFields":["Telling version (4 lines)","Showing version (4 lines)"],"selfCheck":"Does your 'showing' version avoid naming the emotion directly?","reflection":"Which version would you rather hear in a song?"},{"id":"1.16","title":"Destination Writing & Columns","source":"Stolpe, Popular Lyric Writing ch2–3","purpose":"Destination writing directs your senses at a specific who, where, or when. Splitting into External (concrete, sensory) and Internal (thought, feeling) columns gives you raw material organized for songwriting.","instructions":["Choose a keyword: a person, place, or time that matters to you.","Set the timer for 10 minutes. Write freely, aiming your senses at that destination.","After writing, go through phrase by phrase:","- Mark each phrase as E (external/sensory) or I (internal/thought-feeling).","- Arrange them in two columns."],"constraints":"10 minutes","outputFields":["Destination keyword","Full writing","External column phrases","Internal column phrases"],"toolLink":"object-writing","selfCheck":"Do you have at least 3 phrases in each column?"},{"id":"1.17","title":"Powerhouse Verbs","source":"Stolpe, Popular Lyric Writing ch1, ch10","purpose":"Generic verbs (go, get, feel, be, make) weaken lyrics. Specific verbs create vivid pictures and carry more emotional weight.","instructions":["Take your destination writing from exercise 1.16.","Circle every generic verb: go, get, feel, be, make, do, have, seem, look.","For each one, brainstorm three specific alternatives.","Rewrite the passage with your powerhouse verbs."],"outputFields":["Generic verbs found","Replacements for each","Rewritten passage"],"selfCheck":"Read the before/after aloud. Does the rewrite create stronger images?"},{"id":"1.18","title":"Airport Game","source":"Pattison, WBL ch1","purpose":"Build character empathy quickly by asking questions about a stranger — real or imagined. This is a songwriter's version of people-watching.","instructions":["Think of a stranger you've seen (or invent one).","Answer these questions about them: What's in their bag? What did they eat for breakfast? What do they regret? What's their happiest memory? What are they avoiding? What sound do they associate with home?","Now write 5 minutes of object writing from THEIR perspective, using THEIR senses."],"constraints":"5 minutes for the writing portion","outputFields":["Character description","Six answers","5-minute object writing as them"],"selfCheck":"Did you stay in their perspective, not yours?"}],"stageSong":"A 4-line verse built entirely from images harvested from your 14 days of object writing."},{"id":2,"name":"Home Base","subtitle":"Harmony Foundations","promise":"Hear chord colors and feel the pull of 'home' — build grooves that move.","books":["Hooktheory I ch1–2","Kachulis, Harmony Units I–III"],"exercises":[{"id":"2.1","title":"One-Chord Groove","source":"Kachulis, Harmony L1","purpose":"A groove is a rhythmic pattern on a single chord that creates feel and energy. This is the foundation of all accompaniment.","instructions":["Open the Groove Maker.","Choose a single chord (try C major).","Create a 1-bar rhythmic pattern using the 16-step grid.","Play it back. Does it make you nod your head?","Try different patterns until one feels good."],"outputFields":["Groove pattern description","Tempo","Feel"],"toolLink":"groove-maker","selfCheck":"Does your groove make you want to move?"},{"id":"2.2","title":"Develop the Groove","source":"Kachulis, Harmony L2","purpose":"Learn three fundamental development techniques that turn a 1-bar idea into an 8-bar section.","instructions":["Take your groove from 2.1.","Make three 8-bar versions:","1) Exact repetition: repeat your bar 8 times.","2) Varied repetition: change one element every other bar.","3) Two motives: create a second contrasting pattern and alternate."],"outputFields":["8-bar exact repetition notes","8-bar varied repetition notes","8-bar two-motive notes"],"toolLink":"groove-maker","selfCheck":"Does each version feel like a complete section?"},{"id":"2.3","title":"Four Chord Colors","source":"Kachulis, Harmony L3–6","purpose":"Each chord quality (major, minor, power, seventh) carries a distinct emotional color. Training yourself to hear and name these colors is essential for choosing chords that match your lyrics.","instructions":["At your piano or in the Chord Lab, play these four chords slowly:","C major — listen and feel. What emotion? What color? What title might it suggest?","A minor — same questions.","E5 (power chord, root + fifth only) — same questions.","G7 (dominant seventh) — same questions.","Write your impressions for each."],"outputFields":["C major: emotion, color, title","A minor: emotion, color, title","E5: emotion, color, title","G7: emotion, color, title"],"toolLink":"chord-lab","selfCheck":"Can you hear the difference between all four with eyes closed?"},{"id":"2.4","title":"Color Variations","source":"Kachulis, Harmony L7–8","purpose":"Adding extensions (add2, sus4, maj7, 6, etc.) to a chord changes its color subtly — like adjusting the shade of a paint color.","instructions":["Pick one chord (e.g., C major).","In the Chord Lab, audition these variations: Cadd2, Csus4, Cmaj7, C6.","For each, note how the color shifts.","Build a groove that alternates between two variations (e.g., C ↔ Csus4)."],"outputFields":["Chord chosen","Variation impressions","Groove description"],"toolLink":"chord-lab"},{"id":"2.5","title":"Hearing Home","source":"Hooktheory I ch2.1","purpose":"The I chord is 'home' — the place of rest and resolution. Training your ear to feel this pull is the foundation of all harmonic understanding.","instructions":["In the Chord Lab, play: I – IV – V – I in C major.","Close your eyes. Notice how the last chord feels like arriving.","Now play: I – IV – V – vi. Notice how NOT landing on I creates tension.","Try several progressions. Mark where the I chord appears.","The pull toward I is the most powerful force in tonal music."],"outputFields":["Progressions tried","Notes on how I chord feels"],"toolLink":"chord-lab","selfCheck":"Can you feel the difference between ending on I vs. not?"},{"id":"2.6","title":"Chord Functions & Cadences","source":"Hooktheory I ch2.2–2.3","purpose":"Chords have functions: some feel stable (I, vi), some create tension that wants to resolve (V, vii°), and some prepare that tension (ii, IV). Cadences are standard endings that use these functions.","instructions":["Build four 4-chord progressions using I, IV, V, and vi.","End each with a different cadence:","1) V → I (full cadence: strong resolution)","2) → V (half cadence: pause, not resolution)","3) V → vi (deceptive: surprise detour)","4) IV → I (plagal: gentle 'amen' ending)","Play each and note the different feelings."],"outputFields":["Progression 1 (full cadence)","Progression 2 (half cadence)","Progression 3 (deceptive)","Progression 4 (plagal)","Feeling notes"],"toolLink":"chord-lab"},{"id":"2.7","title":"Key Colors","source":"Kachulis, Harmony L9–13","purpose":"Beyond major and minor, there are distinct harmonic 'colors' — Mixolydian, Dorian, and blues — each with a characteristic mood useful in pop and jazz.","instructions":["Write a simple 2-chord groove in each key color:","Major: I – IV (bright, optimistic)","Minor: i – bVII (dark, dramatic)","Mixolydian: I – bVII (rootsy, rock)","Dorian: i7 – IV7 (soulful, jazzy)","Blues: I7 – IV7 (gritty, funky)","Note the mood of each."],"outputFields":["Major groove & mood","Minor groove & mood","Mixolydian groove & mood","Dorian groove & mood","Blues groove & mood"],"toolLink":"chord-lab"},{"id":"2.8","title":"Colors Outside the Key","source":"Kachulis, Harmony L14","purpose":"Borrowing chords from outside the key adds color and surprise — like a splash of unexpected paint. Three techniques: borrowed type, borrowed root, and secondary dominants.","instructions":["In C major, try these 'outside' chords:","Borrowed type: play Fmaj7, then change it to F7. Hear how the character shifts.","Borrowed root: play Fm (iv from C minor). Notice the bittersweet quality.","Secondary dominant: play A7 → Dm. The A7 doesn't belong in C major but it 'points' strongly to Dm.","Record your impressions."],"outputFields":["Borrowed type impression","Borrowed root impression","Secondary dominant impression"],"toolLink":"chord-lab"},{"id":"2.9","title":"Contrasting Sections","source":"Kachulis, Harmony L16","purpose":"The simplest way to contrast a verse and chorus harmonically is to change the number of chords or the harmonic color.","instructions":["Create a verse using just 1 chord (a groove).","Create a chorus that uses a 2–4 chord progression.","Play them back to back.","Notice how the addition of chord motion in the chorus creates lift and energy."],"outputFields":["Verse (1-chord groove)","Chorus (progression)","Contrast notes"],"toolLink":"chord-lab"},{"id":"2.10","title":"Six Grooves of One Progression","source":"Kachulis, Harmony L16–18","purpose":"Kachulis's four groove choices are tempo, feel (style), rhythmic level, and rhythmic idea. By playing the same chords in six different rhythm styles you experience how groove transforms harmony — the same I–V–vi–IV can be a ballad, a bossa, or a funk jam.","instructions":["In the Chord Lab, build a 4-chord progression (try I–V–vi–IV).","Open the Style Browser and play the progression in six different styles from at least three families (e.g. Pop Ballad, Bossa Nova, Jazz Swing, Reggae, Funk, Samba).","For each style, note: does the progression feel happy, sad, cool, driving, or something else? Which style surprised you most?","Save your favorite groove as a seed."],"outputFields":["Progression used","Style 1 & feel","Style 2 & feel","Style 3 & feel","Style 4 & feel","Style 5 & feel","Style 6 & feel","Most surprising style & why"],"toolLink":"chord-lab","selfCheck":"Did you try styles from at least three different families?"}],"stageSong":"A verse + chorus groove with a talk-sung melody over it."},{"id":3,"name":"Words in Time","subtitle":"Stress & Meter","promise":"Hear the rhythm inside language — make words and music dance together.","books":["SWB Challenge 4 D1–10","Pattison, WBL ch14–17","Berklee Shares Lyric Form"],"exercises":[{"id":"3.1","title":"Stress Detective","source":"Pattison, WBL ch14","purpose":"Lyrics are measured by stressed syllables, not syllable count. Learning to hear stress patterns is the key to making words fit music naturally.","instructions":["Type out 5 lines from a song you love.","Read each line aloud naturally.","Tap or mark the stressed syllables.","Count the stresses per line (this is the line's 'length' in songwriting)."],"outputFields":["5 lines with stresses marked","Stress count per line"],"toolLink":"lyric-sheet","selfCheck":"Read your stress marks aloud. Do they match natural speech?"},{"id":"3.2","title":"Juggling Four Balls","source":"Berklee Shares, Essential Guide to Lyric Form & Structure","purpose":"Lyric writing juggles four elements simultaneously: number of phrases, phrase length, phrase rhythm, and rhyme arrangement. Awareness of all four gives you control over structure.","instructions":["Choose one verse from a song you admire.","Analyze it for all four elements:","1) Number of phrases (how many lines/musical phrases?)","2) Phrase length (how many stresses per phrase?)","3) Rhythm of phrases (are stress patterns regular or varied?)","4) Rhyme arrangement (which lines rhyme? what pattern?)","Write your analysis."],"outputFields":["Song & verse chosen","Number of phrases","Phrase lengths","Rhythm pattern","Rhyme arrangement"],"toolLink":"lyric-sheet"},{"id":"3.3","title":"Tetrameter Lines","source":"Pattison, SWB Challenge 4 Days 1–2","purpose":"Tetrameter (4-stress lines) is the most common line length in English-language songs. Writing sense-bound content in this rhythm trains you to think in musical phrases.","instructions":["Set timer for 10 minutes.","Write freely but in 4-stress lines (each line has exactly 4 strong beats).","Try duple feel first (da-DUM da-DUM da-DUM da-DUM).","Then try triple feel (da-da-DUM da-da-DUM da-da-DUM da-da-DUM).","Keep the seven senses engaged — this is object writing in meter."],"constraints":"10 minutes","outputFields":["Duple-feel tetrameter lines","Triple-feel tetrameter lines"],"toolLink":"object-writing","selfCheck":"Read each line aloud. Does every line have exactly 4 stresses?"},{"id":"3.4","title":"Tetrameter Couplets","source":"Pattison, SWB Challenge 4 Days 3–6","purpose":"Couplets (two rhyming lines of equal length) are the simplest closed structure. They feel resolved and complete — useful for choruses and refrains.","instructions":["Write 4 pairs of rhyming tetrameter couplets.","First 2 pairs: duple feel (da-DUM pattern).","Next 2 pairs: triple feel (da-da-DUM pattern).","Use sense-bound language throughout."],"constraints":"10 minutes","outputFields":["Duple couplet 1","Duple couplet 2","Triple couplet 1","Triple couplet 2"],"selfCheck":"Do the rhymes feel natural, not forced? Do stresses match?"},{"id":"3.5","title":"Common Meter","source":"Pattison, SWB Challenge 4 Days 7–10","purpose":"Common meter (4/3/4/3 stresses, like 'Amazing Grace') is the most versatile pattern in English lyric writing. The alternating long-short creates gentle forward motion.","instructions":["Write two 4-line stanzas in common meter:","Line 1: 4 stresses","Line 2: 3 stresses","Line 3: 4 stresses","Line 4: 3 stresses","First stanza: xaxa rhyme (only lines 2 & 4 rhyme).","Second stanza: abab rhyme (lines 1&3 rhyme, 2&4 rhyme)."],"outputFields":["Common meter xaxa stanza","Common meter abab stanza"],"selfCheck":"Does each stanza feel like it could be sung?"},{"id":"3.6","title":"Un-March the Couplets","source":"Pattison, WBL ch17","purpose":"Too many matched couplets create a 'marching' feel — predictable and rigid. Three techniques break the march: unrhyming, shortening, and adding longer rhymed lines.","instructions":["Write four matched couplet lines (4/4/4/4 stresses, aabb).","Now 'un-march' them three ways:","1) Unrhyme the first couplet: change aabb → xabb.","2) Shorten line 2: change 4/4/4/4 → 4/3/4/4.","3) Add rhymed 5-stress lines to create xxaxxa (4/3/5/4/3/5).","Compare how each version feels."],"outputFields":["Original couplets (aabb)","Unrhymed version (xabb)","Shortened version","Extended version (xxaxxa)","Comparison notes"],"toolLink":"lyric-sheet","selfCheck":"Which version has the most interesting motion?"},{"id":"3.7","title":"Spotlight with Deceptive Closure","source":"Pattison, WBL ch15","purpose":"An ABAA rhyme scheme creates 'deceptive closure' — the ear expects the B rhyme to return but instead hears A again. This spotlights the final line.","instructions":["Write a common-meter quatrain with an ABAB scheme.","Now rewrite line 4 so it rhymes with lines 1 and 3 instead (making ABAA).","Read both versions aloud.","Feel how ABAA puts a spotlight on line 4 — it surprises the ear."],"outputFields":["ABAB version","ABAA version","What the spotlight reveals"],"toolLink":"lyric-sheet","selfCheck":"Does line 4 in the ABAA version feel like the most important line?"}],"stageSong":"A common-meter verse and couplet chorus."},{"id":4,"name":"Melody I: Rhythm","subtitle":"Rhythmic Melody","promise":"Shape melodies in time before worrying about pitch — rhythm is melody's skeleton.","books":["Kachulis, Melody Unit I","Hooktheory I ch3.2"],"exercises":[{"id":"4.1","title":"Note Lengths","source":"Kachulis, Melody L1","purpose":"Long notes create space and emphasis; short notes create energy and motion. Mixing them is how melodies breathe.","instructions":["Choose a 4-chord progression.","Sing your title on long notes (whole/half notes).","Sing the same title on short notes (eighth notes).","Now mix: long title, short supporting words.","Record which version best serves the title."],"outputFields":["Long-note version","Short-note version","Mixed version","Best version & why"],"toolLink":"melody-sketcher","levels":["Practice","Set Your Own Lyrics","Rewrite the Hits","Write a Song"]},{"id":"4.2","title":"Phrase Length & Space","source":"Kachulis, Melody L2","purpose":"Space (silence) before or after the title draws the listener's ear. A title surrounded by space becomes the most important moment.","instructions":["Write a 2-phrase melody.","Leave space (rest) before your title phrase.","Try: space after instead.","Try: title phrase alone with space on both sides.","Which placement makes the title land hardest?"],"outputFields":["Melody with space before title","Space after title","Space on both sides","Best placement & why"],"toolLink":"melody-sketcher","levels":["Practice","Set Your Own Lyrics","Rewrite the Hits","Write a Song"]},{"id":"4.3","title":"Phrase Beginnings","source":"Kachulis, Melody L3","purpose":"Where a phrase begins relative to the downbeat affects energy. On the beat is neutral; before the beat (pickup) creates anticipation; after the beat creates a relaxed or surprising feel.","instructions":["Take a title that starts with a stressed syllable.","Sing it three ways:","1) Starting ON the downbeat (neutral, strong)","2) Starting BEFORE the downbeat (pickup, anticipation)","3) Starting AFTER the downbeat (delayed, relaxed)","For a title with an unstressed first syllable, it works best before or after — not on the downbeat."],"outputFields":["Title used","On-beat version","Before-beat version","After-beat version","Best feel & why"],"toolLink":"melody-sketcher","levels":["Practice","Set Your Own Lyrics","Rewrite the Hits","Write a Song"]},{"id":"4.4","title":"Phrase Endings","source":"Kachulis, Melody L4","purpose":"Masculine endings (one syllable on a strong beat) feel definitive. Feminine endings (two syllables, stress then unstress) feel softer or questioning.","instructions":["Write two versions of a title phrase:","1) Ending on one stressed syllable (masculine: 'Let me GO')","2) Ending on stress-then-unstress (feminine: 'I REMember')","Sing both over the same chord. Note the different energy."],"outputFields":["Masculine ending phrase","Feminine ending phrase","Energy comparison"],"toolLink":"melody-sketcher","levels":["Practice","Set Your Own Lyrics","Rewrite the Hits","Write a Song"]},{"id":"4.5","title":"Title on the Downbeat","source":"Kachulis, Melody L5","purpose":"Placing your title so it lands on a strong beat makes it memorable and singable.","instructions":["Take your title.","Arrange the preceding words so the first stressed syllable of the title falls exactly on beat 1 of a bar.","Sing it. Does the title 'pop'?"],"outputFields":["Title and phrasing","Notes on impact"],"toolLink":"melody-sketcher","levels":["Practice","Set Your Own Lyrics","Rewrite the Hits","Write a Song"]},{"id":"4.6","title":"Exact Repetition → Chorus","source":"Kachulis, Melody L6","purpose":"Repeating a melodic phrase exactly is the most powerful tool for making a melody stick. Choruses rely on this.","instructions":["Write a 2-bar melodic phrase for your chorus.","Repeat it exactly.","This 4-bar unit IS your chorus melody's foundation.","Sing it 4 times. Is it memorable?"],"outputFields":["Chorus phrase (2 bars)","Notes on memorability"],"toolLink":"melody-sketcher","levels":["Practice","Set Your Own Lyrics","Rewrite the Hits","Write a Song"]},{"id":"4.7","title":"Varied Repetition","source":"Kachulis, Melody L7","purpose":"Varying the end of a repeated phrase keeps interest while maintaining recognition. This is how verses typically work — same start, different end.","instructions":["Take the phrase from 4.6.","Repeat it but change the last 2–3 notes.","The beginning sounds familiar; the ending goes somewhere new.","This creates the 'same but different' feel of a verse melody."],"outputFields":["Original phrase","Varied version","What changed"],"toolLink":"melody-sketcher","levels":["Practice","Set Your Own Lyrics","Rewrite the Hits","Write a Song"]},{"id":"4.8","title":"Internal Repetition: Tease the Title","source":"Kachulis, Melody L8","purpose":"Breaking the title into fragments and repeating them through the chorus builds anticipation before delivering the full title — a powerful hook technique.","instructions":["Take a multi-word title.","Sing just the first word/fragment at the start of a phrase.","Repeat/tease that fragment.","Then deliver the complete title at a climactic moment.","This 'tease and resolve' creates satisfying chorus architecture."],"outputFields":["Title used","Fragment teased","Full delivery moment","Melody sketch"],"toolLink":"melody-sketcher","levels":["Practice","Set Your Own Lyrics","Rewrite the Hits","Write a Song"]},{"id":"4.9","title":"Contrasting Ideas","source":"Kachulis, Melody L9","purpose":"Introducing a completely different melodic idea creates contrast — essential for keeping a song interesting across sections.","instructions":["Write Idea A: a 4-bar phrase.","Write Idea B: a contrasting 4-bar phrase (different rhythm, different range, different energy).","Play A then B. Does B provide relief/contrast from A?"],"outputFields":["Idea A","Idea B","Contrast notes"],"toolLink":"melody-sketcher","levels":["Practice","Set Your Own Lyrics","Rewrite the Hits","Write a Song"]},{"id":"4.10","title":"Number of Phrases","source":"Kachulis, Melody L10","purpose":"The number of phrases in a section affects balance. Even numbers (4, 6) feel stable; odd numbers (3, 5) create asymmetry and forward motion.","instructions":["Write a section with 4 phrases (stable, balanced).","Write one with 5 phrases (the extra phrase pushes forward).","Write one with 3 phrases (incomplete, wants more).","Choose the count that fits your section's emotion."],"outputFields":["4-phrase version","5-phrase version","3-phrase version","Best fit & why"],"toolLink":"melody-sketcher","levels":["Practice","Set Your Own Lyrics","Rewrite the Hits","Write a Song"]},{"id":"4.11","title":"Contrasting Sections","source":"Kachulis, Melody L11","purpose":"Verse and chorus should feel different melodically. Contrast comes from changing rhythm, range, phrase count, or density.","instructions":["Write a verse melody (more rhythmic variety, moderate range).","Write a chorus melody (simpler rhythm, higher range, more repetition).","Play them back to back. The chorus should feel like an arrival."],"outputFields":["Verse melody sketch","Chorus melody sketch","Contrast achieved"],"toolLink":"melody-sketcher","levels":["Practice","Set Your Own Lyrics","Rewrite the Hits","Write a Song"]}],"stageSong":"Verse/prechorus/chorus using rhythm tools only (melody on just a few notes)."},{"id":5,"name":"Rhyme & Metaphor","subtitle":"The Sound of Meaning","promise":"Make rhyme a precision tool and metaphor a discovery engine.","books":["Pattison, WBL ch3–5","SWB Challenges 2–3","Stolpe ch4"],"exercises":[{"id":"5.1","title":"Five Rhyme Types Grid","source":"Stolpe, Popular Lyric Writing ch4; Pattison WBL ch4","purpose":"There are five types of rhyme, from tightest to loosest: perfect, family, additive/subtractive, assonance, and consonance. Each creates a different degree of resolution — like chord voicings of the tonic.","instructions":["For each word below, find one rhyme of each type:","Words: wrong, run, confuse, light, track, boat.","Perfect: same vowel + same following consonants.","Family: same vowel + consonants from the same phonetic family.","Additive/Subtractive: one word adds or drops a consonant.","Assonance: same vowel, unrelated consonants.","Consonance: different vowel, same final consonants."],"outputFields":["wrong: P/F/A-S/Asn/Con","run: P/F/A-S/Asn/Con","confuse: P/F/A-S/Asn/Con","light: P/F/A-S/Asn/Con","track: P/F/A-S/Asn/Con","boat: P/F/A-S/Asn/Con"],"toolLink":"rhyme-bench","selfCheck":"Can you explain why each rhyme fits its category?"},{"id":"5.2","title":"Rhyme as Chords","source":"Pattison, WBL ch4","purpose":"Pattison's brilliant analogy: rhyme types behave like chord voicings of the tonic. Perfect rhyme is the root-position triad; each step weaker adds openness and longing — like inversions. Hearing this makes rhyme choice musical.","instructions":["Write a stable couplet with a perfect rhyme.","Rewrite the end-word through all five rhyme types, keeping the meaning as close as possible.","For each version, play the corresponding chord voicing in the Rhyme Workbench.","Note how the feeling changes from closed to open."],"outputFields":["Perfect rhyme couplet","Family rhyme version","Additive/subtractive version","Assonance version","Consonance version","Feeling progression notes"],"toolLink":"rhyme-bench"},{"id":"5.3","title":"Family Rhyme Hunt","source":"Pattison, WBL ch4","purpose":"Family rhymes (same vowel, consonants from the same phonetic family) open up vastly more options than perfect rhyme while still sounding satisfying.","instructions":["Take three end-words from your recent lyrics.","For each, find family rhymes using the consonant families:","Plosives: b, d, g / p, t, k","Fricatives: v, th(voiced), z, zh, j / f, th(voiceless), s, sh, ch","Nasals: m, n, ng","List at least 3 family rhymes per word."],"outputFields":["Word 1 + family rhymes","Word 2 + family rhymes","Word 3 + family rhymes"],"toolLink":"rhyme-bench"},{"id":"5.4","title":"Cliché Detox","source":"Pattison, WBL ch5","purpose":"Certain rhyme pairs are so overused they signal 'amateur' — not because the words are bad, but because the pairing is automatic. Catching them lets you make conscious choices.","instructions":["Review your last three pieces of lyric writing.","Flag any of these common cliché pairs: heart/apart, fire/desire, love/above, pain/rain, night/light, forever/together, cry/goodbye, eyes/realize, touch/much, true/blue, baby/maybe, arms/charms, tears/fears.","For each one found, replace it with a family or assonance rhyme that says something more specific.","Note: clichés are fine as placeholders in drafts — just don't keep them."],"outputFields":["Clichés found","Replacements"],"selfCheck":"Do your replacements say something more specific than the clichés?"},{"id":"5.5","title":"Build a Worksheet","source":"Pattison, WBL ch4","purpose":"The worksheet is Pattison's core pre-writing tool: focus your idea, generate keywords sharing the title's key vowel sounds, then map rhyme options across all five types. 'The more you can say no, the better.'","instructions":["Choose an idea for your next lyric.","Write a one-sentence focus statement.","List 15–20 keywords related to your idea. Include:","- Words sharing the title's key vowel sound","- Words ending on stressed syllables (these rhyme better)","- Put words that share a vowel sound in parentheses together.","For each keyword, look up rhymes in all five types.","Use this worksheet to write your next lyric."],"outputFields":["Idea focus","Keyword list","Rhyme columns (at least 5 keywords)"],"toolLink":"rhyme-bench","selfCheck":"Do you have at least 3 rhyme options per keyword?"},{"id":"5.6","title":"Rhyme Pairs from Columns","source":"Stolpe, Popular Lyric Writing ch4","purpose":"Your External/Internal columns from destination writing are a goldmine for rhyme pairs that already carry your theme's meaning.","instructions":["Return to your E/I columns from exercise 1.16.","Look for rhyming phrases — either within one column or across columns.","Pair them up and label the rhyme type.","These natural pairings are the raw material for your next verse."],"outputFields":["Rhyme pairs found","Rhyme types labeled","Strongest pair and why"]},{"id":"5.7","title":"Metaphor Day 1: Adjective–Noun Collisions","source":"Pattison, SWB Challenge 2 Day 1","purpose":"Colliding an adjective with an unrelated noun creates instant metaphor. The surprising combination forces your brain to find meaning — and that meaning is original.","instructions":["Generate 5 adjective–noun collisions.","For each collision/creation, write one sentence or short paragraph making sense of it.","Then set the timer for 90 seconds and do a burst of object writing on your favorite collision."],"constraints":"90 seconds for the object writing burst","outputFields":["Collisions/creations (5)","Best sentence","90-second object writing"],"toolLink":"metaphor-lab","selfCheck":"Is each collision literally false but emotionally true?"},{"id":"5.8","title":"Metaphor Day 2: Finding Nouns from Adjectives","source":"Pattison, SWB Challenge 2 Day 2","purpose":"Given an adjective, finding nouns it could surprisingly describe builds your collision vocabulary.","instructions":["Generate 5 finding nouns from adjectives.","For each collision/creation, write one sentence or short paragraph making sense of it.","Then set the timer for 90 seconds and do a burst of object writing on your favorite collision."],"constraints":"90 seconds for the object writing burst","outputFields":["Collisions/creations (5)","Best sentence","90-second object writing"],"toolLink":"metaphor-lab","selfCheck":"Is each collision literally false but emotionally true?"},{"id":"5.9","title":"Metaphor Day 3: Adjectives from Nouns","source":"Pattison, SWB Challenge 2 Day 3","purpose":"Reversing the process: given a noun, what unexpected adjectives could describe it?","instructions":["Generate 5 adjectives from nouns.","For each collision/creation, write one sentence or short paragraph making sense of it.","Then set the timer for 90 seconds and do a burst of object writing on your favorite collision."],"constraints":"90 seconds for the object writing burst","outputFields":["Collisions/creations (5)","Best sentence","90-second object writing"],"toolLink":"metaphor-lab","selfCheck":"Is each collision literally false but emotionally true?"},{"id":"5.10","title":"Metaphor Day 4: Noun–Verb Collisions","source":"Pattison, SWB Challenge 2 Day 4","purpose":"Verb-noun collisions create active, vivid imagery. They are the engine of 'show don't tell.'","instructions":["Generate 5 noun–verb collisions.","For each collision/creation, write one sentence or short paragraph making sense of it.","Then set the timer for 90 seconds and do a burst of object writing on your favorite collision."],"constraints":"90 seconds for the object writing burst","outputFields":["Collisions/creations (5)","Best sentence","90-second object writing"],"toolLink":"metaphor-lab","selfCheck":"Is each collision literally false but emotionally true?"},{"id":"5.11","title":"Metaphor Day 5: Verbs from Nouns","source":"Pattison, SWB Challenge 2 Day 5","purpose":"Given a noun, finding unexpected verbs it could perform or receive expands your action vocabulary.","instructions":["Generate 5 verbs from nouns.","For each collision/creation, write one sentence or short paragraph making sense of it.","Then set the timer for 90 seconds and do a burst of object writing on your favorite collision."],"constraints":"90 seconds for the object writing burst","outputFields":["Collisions/creations (5)","Best sentence","90-second object writing"],"toolLink":"metaphor-lab","selfCheck":"Is each collision literally false but emotionally true?"},{"id":"5.12","title":"Metaphor Day 6: Nouns from Verbs","source":"Pattison, SWB Challenge 2 Day 6","purpose":"Reversing: given a verb, what surprising nouns could perform that action?","instructions":["Generate 5 nouns from verbs.","For each collision/creation, write one sentence or short paragraph making sense of it.","Then set the timer for 90 seconds and do a burst of object writing on your favorite collision."],"constraints":"90 seconds for the object writing burst","outputFields":["Collisions/creations (5)","Best sentence","90-second object writing"],"toolLink":"metaphor-lab","selfCheck":"Is each collision literally false but emotionally true?"},{"id":"5.13","title":"Metaphor Day 7: Expressed Identity I","source":"Pattison, SWB Challenge 2 Day 7","purpose":"Expressed identity ('x is y') is metaphor's fundamental form. Three templates: 'x is y', 'the y of x', 'x's y.' Each feels different.","instructions":["Create 5 expressed identity statements using the 'x is y / the y of x / x's y' template(s).","For each collision/creation, write one sentence or short paragraph making sense of it.","Then set the timer for 90 seconds and do a burst of object writing on your favorite collision."],"constraints":"90 seconds for the object writing burst","outputFields":["Collisions/creations (5)","Best sentence","90-second object writing"],"toolLink":"metaphor-lab","selfCheck":"Is each collision literally false but emotionally true?"},{"id":"5.14","title":"Metaphor Day 8: Expressed Identity II","source":"Pattison, SWB Challenge 2 Day 8","purpose":"Continuing expressed identity practice. Building fluency with the three forms.","instructions":["Create 5 expressed identity statements using the 'three forms' template(s).","For each collision/creation, write one sentence or short paragraph making sense of it.","Then set the timer for 90 seconds and do a burst of object writing on your favorite collision."],"constraints":"90 seconds for the object writing burst","outputFields":["Collisions/creations (5)","Best sentence","90-second object writing"],"toolLink":"metaphor-lab","selfCheck":"Is each collision literally false but emotionally true?"},{"id":"5.15","title":"Metaphor Day 9: Nouns from Nouns","source":"Pattison, SWB Challenge 2 Day 9","purpose":"Noun-noun collisions without 'is' create compressed metaphors. The implicit connection is what makes them powerful.","instructions":["Create 5 expressed identity statements using the 'noun + noun' template(s).","For each collision/creation, write one sentence or short paragraph making sense of it.","Then set the timer for 90 seconds and do a burst of object writing on your favorite collision."],"constraints":"90 seconds for the object writing burst","outputFields":["Collisions/creations (5)","Best sentence","90-second object writing"],"toolLink":"metaphor-lab","selfCheck":"Is each collision literally false but emotionally true?"},{"id":"5.16","title":"Metaphor Day 10: Playing in Keys I","source":"Pattison, SWB Challenge 2 Day 10","purpose":"Playing 'in the key' of a word means listing words that are 'diatonic' to it — naturally associated. Then colliding one with something from outside that key creates controlled surprise.","instructions":["Choose a 'key word' and list 10 words 'diatonic' to it. Find 3 collisions with 'outside' words.","For each collision/creation, write one sentence or short paragraph making sense of it.","Then set the timer for 90 seconds and do a burst of object writing on your favorite collision."],"constraints":"90 seconds for the object writing burst","outputFields":["Collisions/creations (5)","Best sentence","90-second object writing"],"toolLink":"metaphor-lab","selfCheck":"Is each collision literally false but emotionally true?"},{"id":"5.17","title":"Metaphor Day 11: Playing in Keys II","source":"Pattison, SWB Challenge 2 Day 11","purpose":"Deeper key-playing: finding the unexpected word that still resonates with the key's feeling.","instructions":["Choose a 'key word' and list 10 words 'diatonic' to it. Find 3 collisions with 'outside' words.","For each collision/creation, write one sentence or short paragraph making sense of it.","Then set the timer for 90 seconds and do a burst of object writing on your favorite collision."],"constraints":"90 seconds for the object writing burst","outputFields":["Collisions/creations (5)","Best sentence","90-second object writing"],"toolLink":"metaphor-lab","selfCheck":"Is each collision literally false but emotionally true?"},{"id":"5.18","title":"Metaphor Day 12: Linking Qualities I","source":"Pattison, SWB Challenge 2 Day 12","purpose":"The bridge from metaphor to songwriting: what quality does my IDEA have? What ELSE has that quality? The 'linking quality' connects your abstract theme to concrete images.","instructions":["Pick an abstract idea. List its qualities. For each quality, find concrete things that share it.","For each collision/creation, write one sentence or short paragraph making sense of it.","Then set the timer for 90 seconds and do a burst of object writing on your favorite collision."],"constraints":"90 seconds for the object writing burst","outputFields":["Collisions/creations (5)","Best sentence","90-second object writing"],"toolLink":"metaphor-lab","selfCheck":"Is each collision literally false but emotionally true?"},{"id":"5.19","title":"Metaphor Day 13: Linking Qualities II","source":"Pattison, SWB Challenge 2 Day 13","purpose":"Practicing linking qualities from the other direction: starting with a concrete image and linking to the abstract idea.","instructions":["Pick an abstract idea. List its qualities. For each quality, find concrete things that share it.","For each collision/creation, write one sentence or short paragraph making sense of it.","Then set the timer for 90 seconds and do a burst of object writing on your favorite collision."],"constraints":"90 seconds for the object writing burst","outputFields":["Collisions/creations (5)","Best sentence","90-second object writing"],"toolLink":"metaphor-lab","selfCheck":"Is each collision literally false but emotionally true?"},{"id":"5.20","title":"Metaphor Day 14: Simile","source":"Pattison, SWB Challenge 2 Day 14","purpose":"Simile ('like' or 'as') is metaphor's sibling. It works best when you need a list of comparisons. Commit to one comparison through the whole song? Use metaphor. Several? Use simile.","instructions":["Write 5 similes for one idea. Choose the one that could sustain an entire song.","For each collision/creation, write one sentence or short paragraph making sense of it.","Then set the timer for 90 seconds and do a burst of object writing on your favorite collision."],"constraints":"90 seconds for the object writing burst","outputFields":["Collisions/creations (5)","Best sentence","90-second object writing"],"toolLink":"metaphor-lab","selfCheck":"Is each collision literally false but emotionally true?"},{"id":"5.21","title":"Object Writing with Metaphor","source":"Pattison, SWB Challenge 3","purpose":"The ultimate combination: aim your sensory writing through a metaphor's lens. If your song is about heartbreak and your metaphor is 'winter,' write about heartbreak using only winter's senses.","instructions":["Choose an object (e.g., 'kitchen').","List its linking qualities (warmth, nourishment, togetherness, mess).","Choose a target idea that shares a quality (e.g., 'new relationship' shares warmth and mess).","Set timer for 10 minutes. Write about the target idea through the object's sensory world.","Harvest the best images."],"constraints":"10 minutes","outputFields":["Object","Linking qualities","Target idea","Metaphor-lens object writing","Harvested images"],"toolLink":"metaphor-lab"}],"stageSong":"A chorus built on one committed metaphor."},{"id":6,"name":"Melody II: Notes","subtitle":"Pitch & Shape","promise":"Give your melodies real pitch — learn to navigate chord tones, stability, and motive development.","books":["Kachulis, Melody Units II–III","Hooktheory I ch3.3–3.6"],"exercises":[{"id":"6.1","title":"One Chord Tone","source":"Kachulis, Melody L12","purpose":"Start simple: sing your title on a single note that belongs to the chord underneath. This ensures stability and lets rhythm do all the work.","instructions":["Pick a chord (e.g., C major = C, E, G).","Choose ONE of its tones.","Sing your title phrase entirely on that one note.","Record it. Even on one note, rhythm makes it musical."],"outputFields":["Chord & tone chosen","Title phrase","Recording notes"],"toolLink":"melody-sketcher","levels":["Practice","Set Your Own Lyrics","Rewrite the Hits","Write a Song"]},{"id":"6.2","title":"Neighbor Notes","source":"Kachulis, Melody L13","purpose":"Neighbor notes (one scale step above or below a chord tone) add gentle motion without leaving the chord's stability zone.","instructions":["Start on a chord tone.","Step up one scale degree, then return.","Step down one scale degree, then return.","Weave neighbor notes into your title phrase."],"outputFields":["Melody with upper neighbors","Melody with lower neighbors","Combined version"],"toolLink":"melody-sketcher","levels":["Practice","Set Your Own Lyrics","Rewrite the Hits","Write a Song"]},{"id":"6.3","title":"Two Chord Tones","source":"Kachulis, Melody L14","purpose":"Moving between two chord tones creates a melodic interval — the first real 'shape' in your melody.","instructions":["Choose two tones from the same chord.","Build a phrase that moves between them.","Try different rhythms on the same two pitches."],"outputFields":["Two tones chosen","Phrase sketch","Best rhythm"],"toolLink":"melody-sketcher","levels":["Practice","Set Your Own Lyrics","Rewrite the Hits","Write a Song"]},{"id":"6.4","title":"Passing Notes","source":"Kachulis, Melody L15; Hooktheory I ch3.4","purpose":"Passing notes fill in the space between chord tones, creating smooth stepwise motion. On weak beats they add color; on strong beats they create tension that should resolve.","instructions":["Connect two chord tones with the scale notes between them.","Place passing notes on weak beats (safe, smooth).","Try one on a strong beat — hear the tension.","Resolve the strong-beat tension by stepping to a chord tone."],"outputFields":["Weak-beat passing notes phrase","Strong-beat tension phrase","Resolution"],"toolLink":"melody-sketcher","levels":["Practice","Set Your Own Lyrics","Rewrite the Hits","Write a Song"]},{"id":"6.5","title":"Arpeggios","source":"Kachulis, Melody L16","purpose":"Singing the chord tones in sequence (arpeggio) creates an open, expansive feel — think of the opening of a national anthem.","instructions":["Choose a chord.","Sing its tones in ascending order, then descending.","Set a lyric phrase to an arpeggiated melody.","Compare with a stepwise (scale) version."],"outputFields":["Arpeggio melody","Scale melody comparison","Which fits better & why"],"toolLink":"melody-sketcher","levels":["Practice","Set Your Own Lyrics","Rewrite the Hits","Write a Song"]},{"id":"6.6","title":"Scales","source":"Kachulis, Melody L17","purpose":"Scale-based melodies (stepwise motion) create smooth, singable lines. Most great melodies are predominantly stepwise with occasional leaps for emphasis.","instructions":["Write a 4-bar melody using primarily stepwise motion.","Add one leap (a third or more) at an emotional peak.","The contrast between steps and the leap creates a highlight."],"outputFields":["Stepwise melody","Added leap location & effect"],"toolLink":"melody-sketcher","levels":["Practice","Set Your Own Lyrics","Rewrite the Hits","Write a Song"]},{"id":"6.7","title":"Stable vs. Unstable","source":"Hooktheory I ch3.3–3.5","purpose":"Notes that belong to the current chord are stable (they can sit on strong beats). Notes outside the chord are unstable and want to resolve. Managing this tension is the art of melody.","instructions":["Over I–IV–vi–V, write a phrase that:","1) Places a chord tone on every strong beat (stable, resolved).","2) Places a non-chord tone on ONE strong beat, then resolves it.","The unstable note should sound 'purposefully tense,' not wrong."],"outputFields":["All-stable version","One-unstable version","Where does the tension resolve?"],"toolLink":"melody-sketcher"},{"id":"6.8","title":"Keep the Rhythm, Change the Shape","source":"Kachulis, Melody L18","purpose":"Separating rhythm from pitch is a superpower. Keeping the same rhythm but changing the pitch contour creates variation with recognition.","instructions":["Write a rhythmic phrase (just the rhythm, no pitch).","Set it to an ascending pitch contour.","Same rhythm, descending contour.","Same rhythm, arch shape (up then down).","Choose the shape that best matches your lyric's emotion."],"outputFields":["Rhythm pattern","Ascending version","Descending version","Arch version","Best fit & why"],"toolLink":"melody-sketcher","levels":["Practice","Set Your Own Lyrics","Rewrite the Hits","Write a Song"]},{"id":"6.9","title":"Repetition & Modified Repetition","source":"Kachulis, Melody L19; Hooktheory I ch3.6","purpose":"Modified repetition adjusts one or two notes of a theme so it fits a new chord while remaining recognizable. This is how melodic themes travel across a chord progression.","instructions":["Write a 2-bar melodic theme over chord 1.","Repeat it exactly over chord 2.","If any note clashes with chord 2, change just that note to the nearest chord tone.","This 'modified repetition' is the bread and butter of melody writing."],"outputFields":["Original theme","Modified version over new chord","Notes changed & why"],"toolLink":"melody-sketcher","levels":["Practice","Set Your Own Lyrics","Rewrite the Hits","Write a Song"]},{"id":"6.10","title":"Sequence","source":"Kachulis, Melody L20; Hooktheory I ch3.6","purpose":"A sequence shifts the entire melodic phrase up or down by a fixed interval. It creates momentum and is one of the most powerful development tools.","instructions":["Write a 2-bar phrase.","Shift the entire phrase up by a step (sequence up).","Shift it down by a step (sequence down).","Three phrases in sequence creates strong forward motion."],"outputFields":["Original phrase","Sequenced up","Sequenced down","3-phrase sequence"],"toolLink":"melody-sketcher","levels":["Practice","Set Your Own Lyrics","Rewrite the Hits","Write a Song"]},{"id":"6.11","title":"Inversion","source":"Kachulis, Melody L21","purpose":"Inverting a melody (flipping its direction: up becomes down, down becomes up) creates a mirror image that feels related but fresh.","instructions":["Take a short phrase.","Invert every interval: if it went up a 3rd, go down a 3rd.","Use the inversion in a different section (e.g., verse melody inverted for prechorus)."],"outputFields":["Original phrase","Inverted phrase","Where it could fit"],"toolLink":"melody-sketcher","levels":["Practice","Set Your Own Lyrics","Rewrite the Hits","Write a Song"]},{"id":"6.12","title":"Shorten & Lengthen the Motive","source":"Kachulis, Melody L22–23","purpose":"Shortening a motive (using just its beginning) creates urgency and acceleration. Lengthening it (adding notes) creates expansion and development.","instructions":["Write a 4-beat motive.","Shorten it to 2 beats. Use the short version as a 'hook fragment.'","Lengthen it to 6 or 8 beats. Use this as a climactic phrase.","A song can use all three lengths of the same motive."],"outputFields":["4-beat motive","Shortened (2-beat) version","Lengthened version","How all three could fit in one song"],"toolLink":"melody-sketcher","levels":["Practice","Set Your Own Lyrics","Rewrite the Hits","Write a Song"]},{"id":"6.13","title":"Connecting Chords & Phrasing","source":"Kachulis, Melody L25–28","purpose":"Melodies must navigate chord changes. In-sync phrasing changes direction with the chords; out-of-sync phrasing floats across chord boundaries, creating a more sophisticated feel.","instructions":["Over a I–IV–V–I progression:","Write an in-sync melody (phrases begin/end with chord changes).","Write an out-of-sync melody (phrases spill across chord boundaries).","Compare: in-sync feels clear and grounded; out-of-sync feels fluid and mature."],"outputFields":["In-sync melody","Out-of-sync melody","Preference & why"],"toolLink":"melody-sketcher"},{"id":"6.14","title":"Melodic Cadences","source":"Kachulis, Melody L29–30","purpose":"Just as chords resolve (V→I), melodies resolve too. A melody landing on scale degree 1 over I chord = maximum rest. Landing elsewhere creates varying degrees of openness.","instructions":["Write a verse melody that ends on scale degree 5 (half cadence — open, unresolved).","Write a chorus melody that ends on scale degree 1 over the I chord (full cadence — complete rest).","The verse wants to continue; the chorus feels finished."],"outputFields":["Verse melody (ends on 5)","Chorus melody (ends on 1)","Resolution comparison"],"toolLink":"melody-sketcher"},{"id":"6.15","title":"Harmonize a Melody","source":"Hooktheory I ch3.6","purpose":"Given a melody, finding chords whose stable tones match the strong-beat melody notes. This is the reverse of writing melody over chords — equally important.","instructions":["Write a simple 4-note melody (one note per bar).","For each note, list all chords from the key that contain it.","Try different chord choices. The melody stays the same but the mood shifts dramatically.","Choose the progression that best supports the lyric's meaning."],"outputFields":["4-note melody","Compatible chords per note","Chosen progression & why"],"toolLink":"chord-lab"},{"id":"6.16","title":"Generate, Sing, Rewrite","source":"Kachulis, Melody Unit IV; Hooktheory I ch3 (the generator is this studio's own, rule-based)","purpose":"A generator can hand you six melodies that obey the tendencies of an emotion, but only singing tells you which one is yours — and only rewriting makes it yours. The rules that made it feel that way are the lesson.","instructions":["Open the Melody Generator and choose an emotion preset.","Generate six melodies over one progression (the \"Six melodies\" batch).","Sing all six. Pick the one that moves you.","Rewrite at least three of its notes by hand in the Melody Sketcher.","Open \"Explain this melody\" and write which rules made it feel the way it does."],"outputFields":["Emotion preset and progression","The melody you picked (scale degrees)","Your rewrite (which notes you changed)","Which rules made it feel that way"],"toolLink":"melody-gen","selfCheck":"Did you change at least three notes — and can you say why each change sounds more like you?"}],"stageSong":"Verse/chorus with a real melody developed from one motive."},{"id":7,"name":"Structure & Motion","subtitle":"Prosody & Form","promise":"Make structure serve emotion — every structural choice either stabilizes or destabilizes.","books":["Pattison, WBL ch18–21","SWB C4 D11–14","Stolpe ch5–6, 8"],"exercises":[{"id":"7.1","title":"Stable or Unstable?","source":"Pattison, WBL ch18","purpose":"Before choosing any structural element, ask: 'Is this section's emotion stable or unstable?' Then build structure to match. This is the core of prosody — appropriate relationships between elements.","instructions":["Think of 5 song ideas or emotions you want to write about.","For each, decide: is the core emotion stable (content, certain, resolved) or unstable (longing, confused, angry, searching)?","Justify each answer.","This decision will guide every structural choice."],"outputFields":["Idea 1 + stability","Idea 2 + stability","Idea 3 + stability","Idea 4 + stability","Idea 5 + stability"],"selfCheck":"Is each stability judgment honest to the emotion, not to what's 'easier' to write?"},{"id":"7.2","title":"Five-Element Analysis","source":"Pattison, WBL ch18–19","purpose":"Every lyric section has five structural elements that create motion (or stillness): number of lines, length of lines, rhythm of lines, rhyme scheme, and rhyme type. Analyzing songs you love reveals how masters use these.","instructions":["Choose one verse or chorus from a song you admire.","Analyze all five elements:","1) Number of lines (even = stable, odd = unstable)","2) Length of lines in stresses (matched = stop, unmatched = go)","3) Rhythm (regular = stable, varied = unstable)","4) Rhyme scheme (ABAB stable, XAXA weaker, XXXX floating)","5) Rhyme type (perfect = closed, assonance = open)","Write the motion notation (A, B, X per line)."],"outputFields":["Song & section","Line count","Line lengths","Rhythm","Rhyme scheme","Rhyme types","Motion notation","Overall: stable or unstable?"],"toolLink":"lyric-sheet"},{"id":"7.3","title":"Motion Lab","source":"Pattison, WBL ch19","purpose":"The same words feel completely different when arranged in different rhyme schemes. This exercise lets you feel motion as a physical sensation.","instructions":["Write a single 4-line idea.","Recast it in each of these schemes:","AAAA (most stable — everything matches)","ABAB (balanced — common meter)","XAXA (open line 1 & 3 create slight push)","ABAA (deceptive closure — spotlights line 4)","ABBA (suspended/floating — In Memoriam stanza)","XXXX (completely unresolved, floating)","Read each aloud. Rank by stability. Pick the one that fits your idea's emotion."],"outputFields":["Original 4 lines","AAAA version","ABAB version","XAXA version","ABAA version","ABBA version","XXXX version","Stability ranking","Best fit & why"],"toolLink":"lyric-sheet"},{"id":"7.4","title":"Five and Six Lines","source":"Pattison, WBL ch19; SWB C4 D11–13","purpose":"Moving beyond quatrains: 5-line sections are inherently unstable (odd = unbalanced); 6-line sections can resolve satisfyingly with patterns like ABCABC.","instructions":["Write a 5-line section with scheme AAAAX. Feel how the last line floats free — very unstable, great for a cliffhanger into the chorus.","Write a 6-line section with ABCABC. Notice how the resolution of all three rhymes creates a satisfying close.","Try XXAXXA (common meter + 5-stress lines). This balances openness with a strong close."],"outputFields":["5-line AAAAX","6-line ABCABC","6-line XXAXXA","Stability comparison"],"toolLink":"lyric-sheet"},{"id":"7.5","title":"Power Positions & Trigger Line","source":"Pattison, WBL ch7","purpose":"The most important positions in any section are the first line, the last line, and any structural surprise. The line immediately before the chorus (the 'trigger line') colors everything the chorus says.","instructions":["Take a verse you've written.","Move your most vivid image or strongest statement to the FIRST line.","Move your most emotionally charged line to the LAST position.","Rewrite the very last line before the chorus so it 'releases' into the chorus — this is your trigger line.","Read: trigger line → chorus title. Does it flow?"],"outputFields":["Original verse","Revised verse with power positions","Trigger line","How it releases into chorus"],"toolLink":"lyric-sheet","selfCheck":"Does the trigger line make you WANT to hear the chorus?"},{"id":"7.6","title":"Toggling Patterns","source":"Stolpe, Popular Lyric Writing ch6","purpose":"Alternating External (sensory) and Internal (thought/feeling) content creates a cinematic effect: the camera shows, then the narrator reflects. Different toggle patterns create different feels.","instructions":["Take a verse idea.","Write it in EEEI toggle pattern with XAXA rhyme (three external images, then one internal insight).","Now rewrite in EIEI pattern with ABAB rhyme (alternating image and insight).","Add prepositions and conjunctions to make both versions conversational.","Compare the two feels."],"outputFields":["EEEI / XAXA version","EIEI / ABAB version","Comparison notes"],"toolLink":"lyric-sheet"},{"id":"7.7","title":"Contrast Design","source":"Stolpe, Popular Lyric Writing ch8","purpose":"The chorus must contrast with the verse as soon as possible. Changing rhyme scheme, rhythm, number of lines, or toggle pattern in the first line of the chorus creates immediate 'this is different' energy.","instructions":["Take a verse (from a previous exercise or new).","Design a chorus that differs in at least 3 of these 4 elements:","1) Rhyme scheme","2) Rhythm of phrases","3) Number of lines","4) Toggle pattern (E/I)","Make the contrast appear in the chorus's first line, not later."],"outputFields":["Verse structure summary","Chorus structure summary","3+ contrasts identified","Chorus draft"],"toolLink":"lyric-sheet"},{"id":"7.8","title":"Balancing Act","source":"Pattison, WBL ch21","purpose":"An even number of phrases balances; an odd number unbalances. Adding or removing a line can spotlight a key phrase or push one section into the next.","instructions":["Write a balanced 4-line verse.","Add one line (making 5). Notice how the odd count creates restlessness.","Use this to spotlight the extra line — make it the most important thought.","The unbalanced verse now 'needs' the chorus to restore balance."],"outputFields":["Balanced 4-line verse","Unbalanced 5-line version","Which line is spotlighted?","How it pushes into the chorus"],"toolLink":"lyric-sheet"},{"id":"7.9","title":"Unstable ABBA","source":"Pattison, SWB Challenge 4 Day 14","purpose":"The ABBA scheme (also called 'In Memoriam' stanza) is suspended and floating — line 1's rhyme doesn't resolve until line 4, creating a held-breath feeling perfect for uncertainty or memory.","instructions":["Write a 4-line piece in ABBA scheme using sense-bound language.","Feel how lines 2–3 are suspended between the A rhymes.","This scheme works beautifully for moments of reflection or uncertainty."],"constraints":"10 minutes","outputFields":["ABBA piece","Emotional effect notes"],"toolLink":"lyric-sheet"}],"stageSong":"A verse/prechorus/chorus where the structure mirrors the section's emotion (stable chorus, unstable verse)."},{"id":8,"name":"Harmony II: Progressions","subtitle":"Power Chords & Color","promise":"Build harmonic journeys — learn to paint with progressions, cadences, and reharmonization.","books":["Kachulis, Harmony IV–VIII","Hooktheory I ch4–5"],"exercises":[{"id":"8.1","title":"Power Progressions by Color","source":"Kachulis, Harmony Unit IV","purpose":"Each key color (major, minor, Mixolydian, Dorian, blues) has characteristic progressions that define its sound. Learn two from each and transpose them to build fluency.","instructions":["Learn two progressions in each key color:","Major: I–IV–V and I–vi–IV–V","Minor: i–bVII–bVI–bVII and i–iv","Mixolydian: I–bVII and I–bVII–IV","Dorian: i7–IV7 and i–ii–bIII–ii","Blues: I7–IV7 and 12-bar blues","Transpose each to C, G, and F (or your 3 favorite keys)."],"outputFields":["Progressions learned (list all)","Keys practiced"],"toolLink":"chord-lab"},{"id":"8.2","title":"The 50s Swap","source":"Hooktheory I ch4.2","purpose":"The ii chord substitutes beautifully for IV because they share two notes. Swapping I–vi–IV–V to I–vi–ii–V creates a subtly different mood — same function, different color.","instructions":["Play I–vi–IV–V in C. Sing a melody.","Now swap IV for ii: I–vi–ii–V.","Sing the same melody. What changed?","Try each in a verse and a chorus. Which fits where?"],"outputFields":["I–vi–IV–V impression","I–vi–ii–V impression","Melody compatibility notes"],"toolLink":"chord-lab"},{"id":"8.3","title":"Using iii","source":"Hooktheory I ch4.1","purpose":"The iii chord feels distant from home — it shares notes with both I and V but doesn't strongly pull in either direction. Use it with care in longer progressions for an ethereal or unexpected quality.","instructions":["Build a 6+ chord progression that includes iii.","Place iii between vi and IV (vi–iii–IV is a classic connection).","Notice how iii adds a moment of floating before IV grounds you again."],"outputFields":["Progression with iii","Where iii sits","Effect notes"],"toolLink":"chord-lab"},{"id":"8.4","title":"Rhythm Variations","source":"Kachulis, Harmony L24–26","purpose":"The same chords feel completely different when you change how long each lasts, where the changes fall, or what order they appear in.","instructions":["Take I–IV–V–I.","Change the LENGTH: make one chord last 2 bars, others 1.","Change the RHYTHM: move the chord change off the downbeat.","Change the ORDER: try V–IV–I, I–V–IV.","Each variation feels like a different song."],"outputFields":["Length variation","Rhythm variation","Order variation","Most interesting & why"],"toolLink":"chord-lab"},{"id":"8.5","title":"Pitch Variations","source":"Kachulis, Harmony L30–33","purpose":"Four ways to vary a progression's pitch content: subtract a chord, add one, replace one, or add a pedal bass note. Each transforms the progression while keeping it recognizable.","instructions":["Start with I–IV–V–vi.","SUBTRACT: remove one chord (e.g., I–IV–vi).","ADD: insert a chord (e.g., I–ii–IV–V–vi).","REPLACE: swap one (e.g., I–IV–V–iii).","PEDAL: hold the bass note on 1 under all chords.","Play each. The pedal version sounds like it never quite leaves home."],"outputFields":["Subtracted version","Added version","Replaced version","Pedal version","Comparison notes"],"toolLink":"chord-lab"},{"id":"8.6","title":"Three Sections from One Progression","source":"Kachulis, Harmony L35","purpose":"A single progression can generate verse, chorus, and bridge through variation — ensuring harmonic unity across the whole song.","instructions":["Choose a 4-chord progression.","Version 1 (verse): play it as-is.","Version 2 (chorus): subtract one chord and add a new one.","Version 3 (bridge): reorder and add a pedal.","You now have three sections that sound related but distinct."],"outputFields":["Base progression","Verse version","Chorus version","Bridge version"],"toolLink":"chord-lab"},{"id":"8.7","title":"Color a Word","source":"Kachulis, Harmony L36","purpose":"One melody note over different chords tells completely different stories. This is reharmonization at its most intimate — changing the MEANING of a single word by changing the chord under it.","instructions":["Choose an important word from a lyric.","Sing it on one note (e.g., G).","In the Chord Lab, audition every chord containing G:","C (G is the 5th), Em (G is the minor 3rd), G (root), Bb (G is the 6th), etc.","Write the emotional story each chord suggests for that word.","Choose the one that matches your lyric's meaning."],"outputFields":["Word chosen","Melody note","Chord auditions & stories","Best chord & why"],"toolLink":"color-word"},{"id":"8.8","title":"Color a Phrase","source":"Kachulis, Harmony L37","purpose":"Extending the color technique to a 2-note phrase multiplies your harmonic options — the chord must contain (or pleasantly color) both notes.","instructions":["Write a 2-note melody phrase.","List chords containing both notes.","List chords containing one note (the other becomes a color tone).","Try each. Which tells the right story?"],"outputFields":["2-note phrase","Chords containing both","Chords with one + color","Best harmonization"],"toolLink":"color-word"},{"id":"8.9","title":"Reharmonize a Section","source":"Kachulis, Harmony L38","purpose":"The full reharmonization method: for each melody note, list all chords containing it, then try them all — basic triads first, then add extensions. The same melody over different chords becomes a different song.","instructions":["Take a melody you've written (or from an exercise).","For each melody note on a strong beat, list compatible chords.","Try basic triads first, then 7ths, then extensions.","Choose the progression that best supports the lyric."],"outputFields":["Original melody + chords","Reharmonized version","What changed in the feel"],"toolLink":"chord-lab"},{"id":"8.10","title":"Cadence Journeys","source":"Kachulis, Harmony L39–43","purpose":"Cadences (endings) control where sections feel like they stop, pause, or continue. 'Home' cadences resolve; 'away' cadences leave things open.","instructions":["Build a verse that ends 'away' (half cadence: last chord is V).","Build a chorus that ends 'home' (full cadence: V → I).","Try a deceptive cadence at the end of a verse (V → vi) — the surprise makes the ear want to keep listening.","Try a plagal cadence for the song's final moment (IV → I, the 'amen')."],"outputFields":["Verse ending away","Chorus ending home","Deceptive cadence","Plagal ending"],"toolLink":"chord-lab"},{"id":"8.11","title":"Bridge: Away/Away","source":"Kachulis, Harmony L47","purpose":"Bridges live in harmonic 'away' territory — they should feel like a departure from both verse and chorus, creating contrast that makes the final chorus feel like a homecoming.","instructions":["Take your verse and chorus progressions.","Build a bridge that:","- Starts on a chord neither verse nor chorus starts on","- Stays 'away' from I for most of its length","- Returns to V or IV at the end to set up the final chorus","The bridge should feel like leaving the room and coming back."],"outputFields":["Verse progression","Chorus progression","Bridge progression","How it sets up the final chorus"],"toolLink":"chord-lab"},{"id":"8.12","title":"Inversions & Pedal","source":"Hooktheory I ch5","purpose":"Bass note inversions (e.g., I/3, V/7) create smooth bass motion. A pedal (holding one bass note under changing chords) delays leaving home, creating anticipation.","instructions":["Over I–V–IV–V:","Add a bass pedal on scale degree 1 under all four chords.","Play without pedal, then with. The pedal version resists leaving home.","Now try inversions: smooth bass walk 1–7–6–7 under the same chords.","Release the pedal at the cadence for maximum resolution."],"outputFields":["Progression without pedal","With pedal","With inversions","Effect of pedal release"],"toolLink":"chord-lab"},{"id":"8.13","title":"Jazz Extension","source":"General practice (jazz application)","purpose":"The ii7–V7–Imaj7 progression is the backbone of jazz harmony. Learning it opens up pop-jazz writing and connects to your Jazz Studio.","instructions":["Play ii7–V7–Imaj7 in C (Dm7–G7–Cmaj7).","Transpose to F and Bb.","Over each, write a 4-bar melody using guide tones (3rds and 7ths of each chord).","Guide tones move by step: the 7th of ii7 becomes the 3rd of V7, etc."],"outputFields":["ii–V–I in 3 keys","Guide-tone melody","How it sounds/feels"],"toolLink":"chord-lab"},{"id":"8.14","title":"Groove Swap — Same Chords, New Life","source":"Kachulis, Harmony L24–26","purpose":"Changing the rhythm style under a progression is the fastest way to reimagine a section. A verse that drags in a ballad may come alive as a bossa; a chorus that feels stiff in straight rock may breathe in a shuffle.","instructions":["Part A — Jazz comping: build a ii–V–I progression and play it in Swing Four (Freddie Green), Charleston Comp, Jazz Waltz, Bossa Nova, and Jazz Ballad. Notice how the same chords take on completely different personalities: energetic vs. cool vs. intimate.","Part B — Groove swap: take a progression from a song you are writing (or use I–vi–ii–V). Play it in three contrasting styles using the Style Browser — choose styles with different tempos, feels, and families.","For each style, listen for: does the progression feel more like a verse, chorus, or bridge? Does the style suggest a different lyric mood?","Pick the best style for each section of your song. Try the A/B Compare feature to switch between two candidates in real time."],"outputFields":["Progression used","Jazz comp impressions (Swing Four / Charleston / Waltz / Bossa / Ballad)","Style A: name, feel, section fit","Style B: name, feel, section fit","Style C: name, feel, section fit","Final choices for verse/chorus/bridge"],"toolLink":"chord-lab","selfCheck":"Did the groove swap suggest a section assignment you hadn't considered?"}],"stageSong":"A song whose chorus feels harmonically 'home' and whose verse feels 'away.'"},{"id":9,"name":"The Story","subtitle":"Song Development","promise":"Build songs that develop — every verse earns the chorus, every section serves the whole.","books":["Pattison, WBL ch6–13","Stolpe ch7, 9, 10"],"exercises":[{"id":"9.1","title":"Boxes Plan","source":"Pattison, WBL ch6–8","purpose":"Each verse/chorus system is a 'box.' Verses must develop so the repeated chorus gains weight each time. Planning boxes before writing prevents the two biggest problems: travelogues (unrelated verses) and verses that don't progress.","instructions":["Choose a song idea.","Summarize each box in ONE sentence:","V1: ___","V2: ___","V3: ___","Chorus: ___","Check: does each verse add new information that makes the chorus mean more?","The chorus should feel heavier after V3 than after V1."],"outputFields":["Song idea","V1 summary","V2 summary","V3 summary","Chorus summary","Does the chorus gain weight? How?"],"toolLink":"song-desk","selfCheck":"Read V1 box → chorus → V2 box → chorus → V3 box → chorus. Does the chorus gain weight each time?"},{"id":"9.2","title":"Travelogue Check","source":"Pattison, WBL ch8","purpose":"A 'travelogue' is when verses jump between unrelated scenes, connected only by the chorus. The fix: ensure each verse leads naturally to the next.","instructions":["Look at your box plan from 9.1.","Between each verse, ask: 'How does the listener get from V1 to V2?'","If the connection is only through the chorus, your verses are a travelogue.","Rewrite the box plan so each verse flows into the next."],"outputFields":["Original box plan","Connection V1→V2","Connection V2→V3","Revised plan if needed"],"selfCheck":"Could you tell the V1→V2→V3 story WITHOUT the chorus?"},{"id":"9.3","title":"You-I-We & Past-Present-Future","source":"Pattison, WBL ch6","purpose":"Two classic formulas for verse progression: You/I/We (perspective broadens) and Past/Present/Future (time moves). Both ensure development.","instructions":["Take a love-song idea.","Write box summaries using You-I-We: V1 about them, V2 about you, V3 about both of you.","Now try Past-Present-Future: V1 how things were, V2 how things are, V3 how things could be.","Choose the formula that fits your idea better."],"outputFields":["You-I-We plan","Past-Present-Future plan","Best fit & why"],"toolLink":"song-desk"},{"id":"9.4","title":"What Happened Before This?","source":"Pattison, WBL ch9","purpose":"Instead of always asking 'what happens next?' — ask 'what happened BEFORE this?' Writing the prior verse often reveals the real story.","instructions":["Take a verse you've written.","Write the verse that comes BEFORE it — the scene or feeling that led to this moment.","Does the new verse make the original stronger?","Consider making the 'before' verse your V1."],"outputFields":["Original verse","The 'before' verse","Does it strengthen the original?","New verse order"],"toolLink":"song-desk"},{"id":"9.5","title":"Point-of-View Check","source":"Pattison, WBL ch10–12","purpose":"Point of view shapes everything. First person is intimate; second person (direct address) allows questions and commands (energy boost); third person creates distance and perspective.","instructions":["Take a chorus you've written or one in progress.","Rewrite it in:","1st person: 'I feel the rain...'","2nd person, direct address: 'You feel the rain...'","3rd person: 'She feels the rain...'","Choose the POV that best serves the song's emotional needs."],"outputFields":["1st person version","2nd person version","3rd person version","Best POV & why"],"toolLink":"lyric-sheet"},{"id":"9.6","title":"Sentence-Type Energy","source":"Pattison, WBL ch6, ch10","purpose":"Changing sentence type (statement → question → command) injects energy into a lyric. Direct address (2nd person) uniquely enables questions and commands.","instructions":["Take a statement from your lyric: 'The light fades slowly.'","Turn it into a question: 'Does the light fade slowly?'","Turn it into a command: 'Watch the light fade slowly.'","Each type creates different energy. Mix them for variety."],"outputFields":["Original statement","Question version","Command version","Where each might fit best"]},{"id":"9.7","title":"Chorus Types & Title Placement","source":"Stolpe, Popular Lyric Writing ch7","purpose":"Two main chorus types: abstract/metaphorical (the title is a figurative statement) and list (the chorus catalogs specifics). Title placement (first line, last line, middle) changes emphasis.","instructions":["Choose a title.","Write an abstract/metaphorical chorus for it.","Write a list chorus for the same title.","Try the title as:","- First line (announces the theme)","- Last line (the payoff — needs a 'bodyguard' line before it)","- Middle line (surrounded by context)","Write a 'bodyguard' line: the line directly before the title that sets it up."],"outputFields":["Title","Abstract chorus","List chorus","Title as first/last/middle","Bodyguard line","Best combination & why"],"toolLink":"lyric-sheet"},{"id":"9.8","title":"Pyramiding","source":"Stolpe, Popular Lyric Writing ch9","purpose":"Pyramiding means each section starts narrow (specific detail) and ends broad (bigger picture). The last line of each section zooms out. Across the whole song, the pyramid grows wider.","instructions":["Take a verse in progress.","Check: does it start with a specific detail?","Does the last line zoom out to a broader statement?","Apply this narrow→broad pattern to each section.","Check the whole song: does V3's ending view encompass more than V1's?"],"outputFields":["Section-by-section narrow→broad check","Whole-song pyramid notes","Revisions made"]},{"id":"9.9","title":"Plot Progressions","source":"Stolpe, Popular Lyric Writing ch7, 9","purpose":"Two proven plot structures: (1) problem→hope?→what if different?→struggles→resolution; (2) how things were→hope?→how things are→it'll be okay. These frameworks prevent aimless lyrics.","instructions":["Take a song idea.","Outline it using Plot Progression 1:","V1: The problem in detail (often past tense)","PC: Is there hope? Does it have to be this way?","CH: What would different feel like?","BR: What struggles must be overcome?","Then outline the same idea using Plot Progression 2:","V: How things used to be / I'd like them to be","PC: Is there hope?","CH: How things actually are","BR: Everything will be okay","Choose one."],"outputFields":["Idea","Plot 1 outline","Plot 2 outline","Better fit & why"],"toolLink":"song-desk"},{"id":"9.10","title":"Second Verse & Bridge","source":"Stolpe ch7, 9; Pattison WBL ch9","purpose":"Second verses should go deeper and more internal than V1. The bridge provides contrast, a new perspective, and gives the final chorus new meaning.","instructions":["Take a song with V1 and chorus written.","Write V2: make it more internal (feelings, thoughts) than V1's external details.","Write a bridge that:","- Starts on a chord neither verse nor chorus starts on","- Provides a new perspective or revelation","- Makes the final chorus mean something new","Check: do V1, V2, and bridge each tell a different part of the story?"],"outputFields":["V2 draft","Bridge draft","How bridge changes the final chorus's meaning"],"toolLink":"song-desk"},{"id":"9.11","title":"Tense Exercise","source":"Stolpe, Popular Lyric Writing ch10","purpose":"Tense inconsistency is one of the most common amateur mistakes. This exercise builds awareness by forcing you to rewrite the same section in three tenses.","instructions":["Take a section from a song in progress.","Rewrite it entirely in PAST tense.","Rewrite it entirely in PRESENT tense.","Rewrite it entirely in FUTURE tense.","Choose the tense that best serves the emotion.","Check: is the chosen tense consistent throughout? (One intentional tense shift is fine; accidental shifts are not.)"],"outputFields":["Past tense version","Present tense version","Future tense version","Best tense & why"],"toolLink":"lyric-sheet"},{"id":"9.12","title":"Conversational Pass","source":"Stolpe, Popular Lyric Writing ch10","purpose":"Great lyrics sound like natural speech, not poetry recitation. Adding conjunctions and prepositions (and, but, so, when, because, from, to) transforms stilted lines into conversational ones.","instructions":["Take a finished verse.","Read it aloud as if talking to a friend.","Where it sounds stilted, add conjunctions (and, but, so, yet) or prepositions (from, to, with, through).","Read the revised version aloud. It should sound like something you'd actually say."],"outputFields":["Original verse","Conversational revision","Words added"],"selfCheck":"Would you actually say this to a friend?"}],"stageSong":"A complete lyric with 3 developing boxes where the chorus gains weight each time."},{"id":10,"name":"Melody III: Colors","subtitle":"Scales & Modes","promise":"Color your melodies with pentatonic, blues, and modal flavors — and play against the bass.","books":["Kachulis, Melody Units IV–V","Kachulis, Harmony IX"],"exercises":[{"id":"10.1","title":"Major Pentatonic on One Chord","source":"Kachulis, Melody L34","purpose":"The major pentatonic scale (1-2-3-5-6) is the sound of pop, country, and gospel melody. It has no half steps, so every note sounds good over the I chord — total melodic freedom.","instructions":["Play a C major chord.","Improvise a melody using ONLY C-D-E-G-A (the C major pentatonic).","Notice: every note sounds consonant. There's no 'wrong' note.","Write a verse melody using only these five notes."],"outputFields":["Pentatonic melody","Feel/mood notes"],"toolLink":"melody-sketcher","levels":["Practice","Set Your Own Lyrics","Rewrite the Hits","Write a Song"]},{"id":"10.2","title":"Major Blues over Progressions","source":"Kachulis, Melody L35–36","purpose":"Adding the 'blue note' (flat 3) to the major pentatonic creates the major blues scale — a bittersweet, soulful sound that works beautifully in pop and jazz.","instructions":["Add Eb to your C major pentatonic: C-D-Eb-E-G-A.","The Eb (blue note) adds tension that resolves to E.","Write a melody over I–IV–V using the major blues scale.","Use the blue note as a passing tone, not as a resting point."],"outputFields":["Major blues melody","Blue note usage notes"],"toolLink":"melody-sketcher","levels":["Practice","Set Your Own Lyrics","Rewrite the Hits","Write a Song"]},{"id":"10.3","title":"Minor Pentatonic & Minor Blues","source":"Kachulis, Melody L37–38","purpose":"The minor pentatonic (1-b3-4-5-b7) is the basis of rock, R&B, and blues melody. Adding the blue note (#4/b5) creates the minor blues scale — raw and emotional.","instructions":["Over A minor, improvise with A-C-D-E-G (A minor pentatonic).","Add Eb (the blue note between D and E) for the minor blues scale.","Write a chorus melody in minor blues.","Compare the feel with major pentatonic — same notes, different starting point, completely different mood."],"outputFields":["Minor pentatonic melody","Minor blues melody","Comparison with major"],"toolLink":"melody-sketcher","levels":["Practice","Set Your Own Lyrics","Rewrite the Hits","Write a Song"]},{"id":"10.4","title":"Mixolydian Melody","source":"Kachulis, Melody L39, L42","purpose":"Mixolydian (major scale with a flat 7th) is the sound of rock, funk, and roots music. The b7 creates a bluesy edge without going full minor.","instructions":["Over C–Bb–F (Mixolydian progression):","Write a melody using the C Mixolydian scale (C-D-E-F-G-A-Bb).","Emphasize the Bb — it's what makes this sound different from plain major.","This is the sound of classic rock choruses and gospel shouts."],"outputFields":["Mixolydian melody","How b7 shapes the feel"],"toolLink":"melody-sketcher","levels":["Practice","Set Your Own Lyrics","Rewrite the Hits","Write a Song"]},{"id":"10.5","title":"Dorian Melody","source":"Kachulis, Melody L40, L43","purpose":"Dorian (minor scale with a raised 6th) is the sound of soul, funk-jazz, and sophisticated minor-key songs. It's brighter than natural minor — melancholy but hopeful.","instructions":["Over Dm7–G7 (Dorian groove):","Write a melody using D Dorian (D-E-F-G-A-B-C).","The B natural (raised 6th) is what distinguishes this from regular D minor.","This mode is everywhere in pop-jazz and neo-soul."],"outputFields":["Dorian melody","Raised 6th effect notes"],"toolLink":"melody-sketcher","levels":["Practice","Set Your Own Lyrics","Rewrite the Hits","Write a Song"]},{"id":"10.6","title":"Motion Against the Bass","source":"Kachulis, Melody L44–47","purpose":"Four types of motion between melody and bass: parallel (same direction), similar (same direction different interval), oblique (one moves, one stays), contrary (opposite directions). Each creates a different texture.","instructions":["Over a bass line that descends (C-B-A-G):","Write a PARALLEL melody (also descending).","Write a CONTRARY melody (ascending while bass descends).","Write an OBLIQUE melody (stays on one note while bass moves).","Contrary motion creates the most drama; oblique creates tension."],"outputFields":["Parallel melody","Contrary melody","Oblique melody","Most effective & why"],"toolLink":"melody-sketcher"},{"id":"10.7","title":"Bass Strategies","source":"Kachulis, Melody L48–50","purpose":"Different bass in verse vs chorus creates structural contrast. Same bass in both creates unity. Riff-based songs use the bass pattern as the primary hook.","instructions":["Write a song structure with:","Verse: bass follows root motion of the chords (different each bar).","Chorus: bass holds a pedal or repeats a riff.","OR: both sections use the same bass riff but different chords above it.","Try a riff-based song where the bass pattern IS the song."],"outputFields":["Verse bass strategy","Chorus bass strategy","Riff experiment","Best approach for your song"],"toolLink":"chord-lab"},{"id":"10.8","title":"Modulation","source":"Kachulis, Harmony L49–53","purpose":"Modulation (changing key) creates the biggest possible contrast. Three types: parallel (C major → C minor), relative (C major → A minor), and surprising (C major → Eb major). Each has a different emotional effect.","instructions":["Write a verse in C major.","PARALLEL modulation: shift to C minor for the bridge.","RELATIVE modulation: shift to A minor.","SURPRISING modulation: shift to Eb major for the last chorus.","Note: modulating UP for the last chorus is a classic energy boost.","Try modulating WITHIN a section (mid-verse key change) for drama."],"outputFields":["Verse in original key","Parallel modulation","Relative modulation","Surprising modulation","Most effective & why"],"toolLink":"chord-lab"},{"id":"10.9","title":"Chord-Scale Map: Improvise, Then Write","source":"General jazz chord-scale pedagogy; Kachulis, Melody Unit IV (pentatonic, blues, Mixolydian, Dorian)","purpose":"Improvising over the changes with the right scale lit up teaches your ear what each chord allows. The best phrase you stumble on is a seed; guide tones and one colour note per chord turn it into a written melody.","instructions":["In the Chord-Scale Map, loop ii–V–I in a key you like, then a 12-bar blues.","Improvise with your voice or at the piano, following the highlighted scale for each chord.","Record the best phrase as a seed.","Turn it into a melody: land on a guide tone (3rd or 7th) on each strong beat, and use one colour note per chord."],"outputFields":["Progressions looped","Best improvised phrase","Guide-tone skeleton","Finished melody (with the colour note for each chord)"],"toolLink":"chord-scale","selfCheck":"Does each chord of your melody have a guide tone on a strong beat and one colour note you can name?"}],"stageSong":"A verse in chord-tone melody and a chorus in pentatonic or blues, OR a complete modal song."}];
